package com.resumethinking.platform.matching;
import jakarta.persistence.*; import java.time.Instant;
@Entity @Table(name="analysis_callback_receipts") public class CallbackReceiptEntity { @Id @Column(name="callback_id",nullable=false,length=64,columnDefinition="VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin") private String callbackId; @Column(name="payload_hash",nullable=false,length=64) private String payloadHash; @Column(name="received_at",nullable=false) private Instant receivedAt; protected CallbackReceiptEntity(){} public CallbackReceiptEntity(CallbackReceipt r){callbackId=r.callbackId();payloadHash=r.payloadHash();receivedAt=r.receivedAt();} public CallbackReceipt toRecord(){return new CallbackReceipt(callbackId,payloadHash,receivedAt);} }
